CREATE TABLE IF NOT EXISTS event_congestion_forecasts (created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, event_congestion_forecast_uuid uuid PRIMARY KEY, event_uuid uuid NOT NULL, generation_input_hash VARCHAR(64) NOT NULL, generated_at TIMESTAMP WITH TIME ZONE NOT NULL);
ALTER TABLE event_congestion_forecasts ADD CONSTRAINT event_congestion_forecasts_event_uuid_unique UNIQUE (event_uuid);
CREATE TABLE IF NOT EXISTS event_congestions (created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, event_congestion_uuid uuid PRIMARY KEY, event_uuid uuid NOT NULL, event_congestion_forecast_uuid uuid NOT NULL, congestion_start_time TIMESTAMP WITH TIME ZONE NOT NULL, congestion_end_time TIMESTAMP WITH TIME ZONE NOT NULL, area TEXT NOT NULL, description TEXT NOT NULL, CONSTRAINT fk_event_congestions_event_congestion_forecast_uuid__event_cong FOREIGN KEY (event_congestion_forecast_uuid) REFERENCES event_congestion_forecasts(event_congestion_forecast_uuid) ON DELETE CASCADE ON UPDATE RESTRICT);
